using System;
using System.Collections.Generic;
using System.Text;

// A whole renderer template, retaining layout offsets, register use and opcodes.
// Only PC-relative code/data addresses are ignored. Changed layouts fail closed.
static class LobbyCompatibility {
 internal static readonly byte[] Template=Convert.FromBase64String("");
 static readonly byte[] Mask=Convert.FromBase64String("");
 internal sealed class Match { internal long Rva; internal byte[] Code; }
 static int I(byte[] b,int at){return BitConverter.ToInt32(b,at);}
 internal static bool Matches(byte[] data,int at){
  if(at<0||at>data.Length-Template.Length)return false;
  for(int i=0;i<Template.Length;i++)if(Mask[i]!=0&&data[at+i]!=Template[i])return false;
  return true;
 }
 internal static Match Find(byte[] file){
  try{return FindCore(file);}catch(Exception e){throw new Exception("This game update is not compatible with the lobby reader. No reader was installed. "+e.Message,e);}
 }
 static Match FindCore(byte[] b){
  if(b.Length<256||b[0]!=77||b[1]!=90)throw new Exception("Invalid executable.");
  int pe=I(b,60);if(I(b,pe)!=0x4550||BitConverter.ToUInt16(b,pe+4)!=0x8664)throw new Exception("Expected a 64-bit game.");
  int count=BitConverter.ToUInt16(b,pe+6),opt=BitConverter.ToUInt16(b,pe+20),sections=pe+24+opt;
  var result=new List<Match>();
  for(int s=0;s<count;s++){
   int h=sections+s*40;if((I(b,h+36)&0x20000000)==0)continue;
   int rva=I(b,h+12),size=I(b,h+16),raw=I(b,h+20);
   if(raw<0||size<0||raw>b.Length-size)throw new Exception("Invalid code section.");
   for(int at=raw;at<=raw+size-Template.Length;at++){
    if(b[at]!=Template[0]||b[at+1]!=Template[1]||!Matches(b,at))continue;
    long candidate=(long)rva+at-raw;bool anchors=true;
    anchors &= Anchor(b,sections,count,candidate+1552+I(b,at+1548),"No public lobbies right now. Host one!");
    anchors &= Anchor(b,sections,count,candidate+3462+I(b,at+3458),"No lobby matches the filters.");
    if(!anchors)continue;
    bool boundary=false;
    for(int p=0;p<count;p++){
     int ph=sections+p*40;
     if(Encoding.ASCII.GetString(b,ph,8).TrimEnd('\0')!=".pdata")continue;
     int pr=I(b,ph+20),ps=I(b,ph+16);
     for(int j=pr;j+12<=pr+ps;j+=12)if(I(b,j)==candidate&&I(b,j+4)==candidate+Template.Length){boundary=true;break;}
    }
    if(!boundary)continue;
    var code=new byte[Template.Length];Array.Copy(b,at,code,0,code.Length);result.Add(new Match{Rva=candidate,Code=code});
   }
  }
  if(result.Count!=1)throw new Exception("Expected one compatible lobby renderer; found "+result.Count+".");
  return result[0];
 }
 static bool Anchor(byte[] b,int sections,int count,long target,string text){
  byte[] expected=Encoding.UTF8.GetBytes(text);
  for(int s=0;s<count;s++){
   int h=sections+s*40;long rv=I(b,h+12);int size=I(b,h+16),raw=I(b,h+20);
   if(target<rv||target+expected.Length>rv+size)continue;
   long pos=raw+target-rv;if(pos<0||pos+expected.Length>b.Length)return false;
   for(int i=0;i<expected.Length;i++)if(b[(int)pos+i]!=expected[i])return false;
   return true;
  }
  return false;
 }
}
